-- APN-MED — Allergiás és immunológiai kórképek.
--
-- Négy kórkép, az akuttól a krónikusig:
--   · anafilaxia — életveszélyes, az elsődleges ellátás ápolói kompetenciába eshet;
--   · krónikus spontán urticaria — gyakori, gondozást igényel;
--   · allergiás rhinitis — a leggyakoribb allergiás kórkép;
--   · herediter angioödéma — ritka, de a felismerés kritikus.
--
-- Az utolsó azért került be, mert a leggyakoribb és legveszélyesebb csapda: ha az
-- arcduzzanatot anafilaxiának kezeljük, a szokásos szerek hatástalanok maradnak,
-- miközben a légút záródik.

insert into public.diseases
  (slug, name, aliases, abbrev, specialty, score_ids, lab_ids, ekg_ids,
   guideline_kw, body, status, version)
values
  ('anafilaxia', 'Anafilaxia', '{"anafilaxiás reakció","anafilaxiás sokk","súlyos allergiás reakció"}', 'Anafilaxia', 'Allergológia és klinikai immunológia', '{"news2","gcs","avpu"}', '{"lact","ph","gluk"}', '{}', '{"anafilaxia","allergia","adrenalin"}', '{"brief_what": "Hirtelen kezdődő, több szervrendszert érintő, súlyos túlérzékenységi reakció, amely percek alatt életveszélyessé válhat.", "brief_why": "A kimenetel az adrenalin beadásának gyorsaságán múlik. A késlekedés a halálos kimenetel legfontosabb megelőzhető tényezője, ezért a felismerés és az azonnali beavatkozás ápolói kulcsfeladat.", "when": ["Ismert vagy feltételezett kiváltó után percekkel–órákkal kezdődő tünetek", "Két vagy több szervrendszer hirtelen érintettsége: bőr, légzés, keringés, emésztés", "Bőrtünet nélkül is: hirtelen vérnyomásesés vagy légúti tünet ismert allergén után", "Leggyakoribb kiváltók: gyógyszer, étel, rovarcsípés, kontrasztanyag, latex"], "examine": ["Légút: rekedtség, stridor, nyelvduzzanat, nyelési nehézség", "Légzés: légzésszám, sípolás, munkalégzés, szaturáció", "Keringés: vérnyomás, pulzus, kapilláris újratelődés, bőrhőmérséklet", "Bőr: csalánkiütés, kipirulás, angioödéma — de hiányuk nem zárja ki", "Tudat: nyugtalanság, zavartság, eszméletvesztés"], "labs": "A diagnózis klinikai, nem laboratóriumi. A szérum-triptáz a reakció kezdetétől számított fél és két óra között vehető le, és utólag támogathatja a kórismét; az alapérték a tünetek teljes megszűnése után legalább 24 órával mérendő. A triptáz normális értéke nem zárja ki az anafilaxiát, és megvárása nem késleltetheti az ellátást.", "ekg": "Nem a diagnózis eszköze. Elhúzódó hypotenzió, mellkasi panasz vagy ismert szívbetegség esetén indokolt, illetve a monitorozás részeként.", "imaging": "Az akut ellátásban nincs szerepe.", "scores": "NEWS2 az állapotromlás követésére, AVPU vagy GCS a tudatállapot rögzítésére. Súlyossági pontozó nem helyettesíti a klinikai megítélést.", "red_flags": ["Stridor, rekedtség, nyelv- vagy garatduzzanat — fenyegető légúti elzáródás", "Vérnyomásesés, gyenge, szapora pulzus, márványozott bőr", "Kimerülés, csökkenő légzési munka romló szaturáció mellett", "Tudatzavar, eszméletvesztés", "Kétfázisú reakció: a tünetek órákkal a javulás után visszatérhetnek", "Bétablokkolót szedő betegnél az adrenalin hatása elmaradhat"], "apn_focus": ["Az adrenalin izomba, a comb középső-külső harmadába adandó — ez az elsődleges beavatkozás, minden más másodlagos", "Fektetés, a láb megemelése; légúti tünetnél ülő helyzet. Hirtelen felültetés vagy felállítás keringésösszeomlást okozhat", "A kiváltó eltávolítása, ha lehetséges (infúzió leállítása, fullánk eltávolítása)", "Nagy űrméretű véna biztosítása, folyadékpótlás előkészítése", "Oxigén adása, folyamatos vitális monitorozás", "A beadás pontos idejének rögzítése — az ismétlés ötpercenként mérlegelhető", "A beteg megfigyelése a kétfázisú reakció miatt; a hazaadás időzítése orvosi döntés", "Adrenalin-autoinjektor felírásának és használatának megbeszélése az elbocsátás előtt"], "treatment": ["Izomba adott adrenalin az elsődleges ellátás — késleltetése a legfontosabb megelőzhető kockázati tényező", "Fektetés, oxigén, intravénás folyadékpótlás", "Antihisztamin és szteroid legfeljebb kiegészítő szerep: a bőrtünetre hatnak, a légúti és keringési összeomlásra nem, és nem helyettesítik az adrenalint", "Elhúzódó vagy adrenalinra nem reagáló esetben intenzív ellátás"], "followup": ["Adrenalin-autoinjektor felírása és a használat gyakoroltatása", "Írásos vészhelyzeti terv a betegnek és a hozzátartozónak", "Allergológiai kivizsgálás a kiváltó azonosítására", "A kiváltó kerülésének megbeszélése, gyógyszerallergia rögzítése a dokumentációban", "Iskolai vagy munkahelyi tájékoztatás, ha indokolt"], "source_name": "EAACI irányelv: Anafilaxia (2021-es frissítés)", "source_url": "https://onlinelibrary.wiley.com/doi/10.1111/all.15032", "version": "2021", "updated": "2026-09-07", "evidence": "Az irányelv maga jelzi, hogy az anafilaxia ellátására vonatkozó bizonyítékok többsége alacsony vagy nagyon alacsony szintű — az adrenalin elsődlegessége mégis egyértelmű ajánlás, mert a késlekedés ártalma jól dokumentált."}'::jsonb, 'published', '1'),
  ('kronikus-urticaria', 'Krónikus spontán urticaria', '{"csalánkiütés","urticaria","krónikus csalánkiütés"}', 'CSU', 'Allergológia és klinikai immunológia', '{}', '{"crp","wbc","tsh"}', '{}', '{"urticaria","csalánkiütés","antihisztamin"}', '{"brief_what": "Hat hétnél hosszabb ideje fennálló, visszatérő csalánkiütés, gyakran angioödémával, azonosítható külső kiváltó nélkül.", "brief_why": "Az életminőséget jelentősen rontja — alvászavart, szorongást és munkaképesség-csökkenést okoz. A kezelés jól algoritmizált, ezért a gondozás és a terápiahűség támogatása érdemi javulást hoz.", "when": ["Hat hétnél régebb óta visszatérő, viszkető csalánfoltok", "Az egyes foltok jellemzően 24 óránál rövidebb ideig állnak fenn, nyom nélkül tűnnek el", "Angioödéma az esetek mintegy felében társul", "Nincs azonosítható külső kiváltó — ez különíti el az indukálható formáktól"], "examine": ["A bőrtünetek jellege, kiterjedése, egyes foltok fennállásának ideje", "Angioödéma jelenléte: szem körül, ajkon, végtagon", "Nyomásfoltok, hegesedés — ezek más kórképre utalnak", "Az életminőség-terhelés felmérése: alvás, munka, közérzet"], "labs": "Rutinszerűen elegendő a vérkép, a CRP és a süllyedés. Széles laborpanel nem javasolt: a találati arány alacsony, és a téves pozitív eredmények fölösleges kivizsgálást indítanak. Célzott vizsgálat akkor indokolt, ha a kórelőzmény vagy a fizikális lelet arra utal.", "ekg": "Nincs szerepe.", "imaging": "Rutinszerűen nem szükséges.", "scores": "Az urticaria-aktivitási pontszám (UAS7) és az életminőség-kérdőívek a követés eszközei; a napi vezetés a betegnek is visszajelzést ad.", "red_flags": ["Az egyes foltok 24 óránál tovább állnak fenn — urticariás vasculitis lehetősége", "A foltok elhalványulás után bőrelszíneződést vagy nyomot hagynak", "Láz, ízületi panasz, fogyás — szisztémás betegség gyanúja", "Izolált angioödéma csalánkiütés nélkül, antihisztaminra nem reagálva — bradikinin-eredetű angioödéma lehetősége, más kezeléssel", "Légúti tünet vagy nyelési nehézség — sürgős ellátás"], "apn_focus": ["A tünetnapló vezetésének megtanítása: mikor, hol, mennyi ideig", "A folyamatos, napi szedés jelentőségének elmagyarázása — a szükség szerinti alkalmazás kevésbé hatékony", "A régi, álmosító antihisztaminok kerülésének megbeszélése", "Az életminőség és az alvás rendszeres felmérése", "A dózisemelés csak orvosi döntés alapján; a betegnek ne saját magának kelljen kísérleteznie", "A tünetek súlyosbodását kiváltó tényezők azonosítása: stressz, láz, gyulladáscsökkentők, alkohol"], "treatment": ["Első vonalban korszerű, nem álmosító, második generációs antihisztamin, szokásos adagban, folyamatosan", "Elégtelen válasz esetén az adag emelése — az irányelv a szokásos négyszereséig engedi, ennél tovább nem javasolt", "Ha ez sem elég, omalizumab jön szóba; a szakellátás dönt róla", "A régi generációs, álmosító antihisztaminok nem javasoltak", "Tartós szteroid nem része a kezelésnek; legfeljebb rövid ideig, fellángoláskor"], "followup": ["Rendszeres aktivitás- és életminőség-mérés", "A kezelés fokozatos leépítése tünetmentesség után, orvosi irányítással", "A betegség jellemzően magától megszűnik, de évekig eltarthat — ennek elmondása sokat segít a beteg türelmén", "Szorongás és alvászavar felmérése, szükség esetén támogatás"], "source_name": "EAACI/GA²LEN/EuroGuiDerm/APAAACI irányelv az urticariáról (2021)", "source_url": "https://onlinelibrary.wiley.com/doi/10.1111/all.15090", "version": "2021", "updated": "2026-09-07", "evidence": "A második generációs antihisztamin első vonalbeli szerepe és az omalizumab hatékonysága magas bizonyossági szintű ajánlás."}'::jsonb, 'published', '1'),
  ('allergias-rhinitis', 'Allergiás rhinitis', '{"szénanátha","allergiás nátha","pollenallergia"}', 'AR', 'Allergológia és klinikai immunológia', '{}', '{}', '{}', '{"rhinitis","allergia","szénanátha"}', '{"brief_what": "Allergén hatására kialakuló orrnyálkahártya-gyulladás: orrfolyás, tüsszögés, orrdugulás és viszketés.", "brief_why": "A leggyakoribb allergiás kórkép, és gyakran alulkezelt. Rontja az alvást, a tanulást és a munkavégzést, emellett szoros kapcsolatban áll az asztmával — a fel nem ismert rhinitis rosszabb asztmakontrollal jár.", "when": ["Orrfolyás, tüsszögés, orrdugulás, orr- és szemviszketés", "Az időbeli mintázat: időszakos vagy tartós, és mennyire terheli a beteget", "Szezonális jelleg vagy állandó kitettség (házipor-atka, állat, penész)", "Társuló asztma, ekcéma vagy ételallergia a kórelőzményben"], "examine": ["Orrnyálkahártya: sápadt, duzzadt; vizes váladék", "Szemtünetek: kötőhártya-pír, könnyezés", "Légzésvizsgálat: sípolás, meghosszabbodott kilégzés — társuló asztma keresése", "Az alvás és a nappali működés terheltségének felmérése"], "labs": "A diagnózis klinikai. A kiváltó azonosítására bőrpróba vagy specifikus IgE szolgál, szakellátásban. Rutin vérkép és CRP nem indokolt.", "ekg": "Nincs szerepe.", "imaging": "Rutinszerűen nem szükséges. Képalkotás akkor jön szóba, ha szövődmény vagy más orrbetegség merül fel.", "scores": "A tünetterhelés és az életminőség mérése (vizuális analóg skála, kérdőívek) segít a kezelés hatásának követésében.", "red_flags": ["Egyoldali orrdugulás vagy véres váladék — más kórkép keresendő", "Szagláscsökkenés, arcfájdalom, tartós tünetek — orrmelléküreg-betegség vagy polip", "Nehézlégzés, sípolás, éjszakai köhögés — asztma irányába terel", "Kezelésre nem javuló, elhúzódó tünetek"], "apn_focus": ["Az orrspray helyes használatának megtanítása — ez a leggyakoribb hibaforrás: a spray az orrsövénytől elfelé, kissé kifelé irányítva adandó", "A folyamatos alkalmazás magyarázata: az orrszteroid hatása napok alatt épül fel, ezért a szükség szerinti használat kevésbé hatékony", "Az orrszűkítő orrcseppek tartós használatának kerülése — visszacsapó orrdugulást okoz", "Allergénkerülési tanácsadás a beteg tényleges körülményeihez igazítva", "Az asztma tüneteinek célzott keresése minden rhinitises betegnél", "Az alvásminőség és a nappali működés felmérése"], "treatment": ["Enyhe, időszakos tüneteknél második generációs antihisztamin szájon át vagy orrspray formájában", "Tartós vagy közepes-súlyos tüneteknél orrszteroid az első választás", "Elégtelen hatás esetén kombinált orrspray (szteroid és antihisztamin együtt)", "Szemtünetekre helyi készítmény", "Allergén-immunterápia mérlegelése tartós, igazolt allergiánál — szakellátásban"], "followup": ["A kezelés hatásának felmérése néhány hét után", "A használati technika ismételt ellenőrzése — az idő múlásával romlik", "Szezonális allergiánál a kezelés megkezdése a pollenidőszak előtt", "Az asztma-kontroll rendszeres ellenőrzése"], "source_name": "ARIA — Allergic Rhinitis and its Impact on Asthma ajánlás", "source_url": "https://www.euforea.eu/", "version": "ARIA", "updated": "2026-09-07", "evidence": "Az orrszteroid elsődlegessége tartós, közepes-súlyos rhinitisben jól megalapozott. Az ajánlások a kezelés időtartamáról nem adnak pontos előírást: tartós forma esetén folyamatos, időszakosnál a panaszos időszakra kiterjedő alkalmazás javasolt."}'::jsonb, 'published', '1'),
  ('herediter-angioodema', 'Herediter angioödéma', '{"örökletes angioödéma","C1-inhibitor hiány","HAE"}', 'HAE', 'Allergológia és klinikai immunológia', '{"news2","avpu"}', '{}', '{}', '{"angioödéma","C1-inhibitor","bradikinin"}', '{"brief_what": "Örökletes, a C1-inhibitor hiányából vagy működészavarából eredő, visszatérő duzzanatokkal járó betegség. A duzzanatot nem hisztamin, hanem bradikinin okozza.", "brief_why": "A legfontosabb csapda a betegségtárban: a roham anafilaxiának látszik, de az adrenalinra, az antihisztaminra és a szteroidra nem reagál. A garatduzzanat fulladásos halált okozhat, ha a felismerés késik.", "when": ["Visszatérő, órák alatt kialakuló duzzanat: arc, ajak, végtag, nemi szervek", "Görcsös hasi fájdalom hányással — a bélfal duzzanata utánozhatja az akut hasat", "Csalánkiütés és viszketés jellemzően NINCS — ez különíti el az allergiás formától", "Családi halmozódás; a tünetek gyakran serdülőkorban kezdődnek", "Kiváltó lehet: sérülés, fogászati vagy sebészi beavatkozás, fertőzés, stressz, ösztrogén tartalmú fogamzásgátló, ACE-gátló"], "examine": ["Légút: hangváltozás, rekedtség, nyelési nehézség, nyelvduzzanat — a legveszélyesebb forma", "A duzzanat jellege: nem viszket, nem melegebb, nem vörös, nyomásra nem marad benyomat", "Csalánkiütés keresése — hiánya erősíti a gyanút", "Hasi vizsgálat görcsös fájdalom esetén", "Az eddigi rohamok gyakoriságának és lefolyásának rögzítése"], "labs": "A kórisme laboratóriumi: C4-komplement, C1-inhibitor mennyisége és működése. Az akut ellátást nem szabad ezek megvárásával késleltetni. A C4 rohamban jellemzően alacsony, de a normális érték a rohamon kívül nem zárja ki teljesen.", "ekg": "Nincs szerepe.", "imaging": "Hasi rohamnál a képalkotás bélfalduzzanatot és szabad hasűri folyadékot mutathat — ez segít elkerülni a fölösleges műtétet.", "scores": "NEWS2 a monitorozáshoz. Súlyossági pontozó nincs; a légúti érintettség önmagában sürgősséget jelent.", "red_flags": ["Bármilyen hangváltozás, rekedtség vagy nyelési nehézség — a légút biztosítása korán mérlegelendő, mert az állapot gyorsan romolhat", "Nyelv- vagy garatduzzanat", "Adrenalinra, antihisztaminra és szteroidra nem reagáló duzzanat — ez maga is diagnosztikus jel", "Erős hasi fájdalom hányással ismert betegnél — hasi roham, nem sebészi kórkép", "ACE-gátlót szedő beteg arcduzzanata — gyógyszer okozta, szintén bradikinin-eredetű forma"], "apn_focus": ["A felismerés a legfontosabb: viszketés és csalánkiütés nélküli, lassan kialakuló, kezelésre nem reagáló duzzanat esetén gondolni kell rá", "A beteg saját gyógyszerének azonnali elérése — a legtöbb beteg magánál hordja, és önmagának is beadhatja", "A rohamot minél korábban kell kezelni; a várakozás rontja a kimenetelt", "Légútfigyelés folyamatosan: hangváltozás, nyelés, nyáladzás", "A beavatkozások előtti megelőzés kérdésének felvetése — fogászati és sebészi beavatkozás gyakori kiváltó", "A dokumentációban jól láthatóan rögzíteni: a szokásos anafilaxia-kezelés hatástalan", "Ösztrogén tartalmú fogamzásgátló és ACE-gátló kerülésének megbeszélése"], "treatment": ["A rohamot célzott szerrel kell kezelni: C1-inhibitor koncentrátum vagy bradikinin-receptor gátló — az adrenalin, az antihisztamin és a szteroid hatástalan", "A kezelés minél korábbi megkezdése javítja a kimenetelt", "Progresszív felső légúti duzzanatnál a légútbiztosítás korai mérlegelése", "Minden betegnek legalább két roham ellátására elegendő gyógyszert kell magánál tartania", "Beavatkozás előtti rövid távú megelőzés mérlegelendő", "Tartós megelőzés szakellátásban, egyénre szabva"], "followup": ["Szakellátási gondozás, egyénre szabott kezelési terv", "Írásos vészhelyzeti terv és tájékoztató kártya a betegnél", "A hozzátartozók oktatása a roham felismerésére és a gyógyszer beadására", "Családtagok szűrésének felvetése — örökletes betegség", "A rohamgyakoriság és a kiváltók naplózása"], "source_name": "WAO/EAACI nemzetközi irányelv a herediter angioödéma kezeléséről (2021-es revízió)", "source_url": "https://onlinelibrary.wiley.com/doi/10.1111/all.15214", "version": "2021", "updated": "2026-09-07", "evidence": "A roham célzott kezelése és a korai beavatkozás erős ajánlás, magas bizonyossági szinttel. A légútbiztosítás korai mérlegelése szakértői egyetértésen alapul."}'::jsonb, 'published', '1')
on conflict (slug) do update set
  name = excluded.name,
  aliases = excluded.aliases,
  specialty = excluded.specialty,
  score_ids = excluded.score_ids,
  lab_ids = excluded.lab_ids,
  guideline_kw = excluded.guideline_kw,
  body = excluded.body,
  status = excluded.status;

-- Ellenőrzés: a négy kórkép létrejött és közzétett állapotban van.
-- Ha itt négy sor jelenik meg, a betegségtárban is látszaniuk kell.
select slug, name, specialty, status, is_stub
from public.diseases
where specialty = 'Allergológia és klinikai immunológia'
order by name;
